) AS (
  VALUES 
    (258::BIGINT, 'Es muy buena persona y muy abierto a ayudar. Es un curso muy fácil la verdad. Si consigue cosas viejas es aún más fácil. Si denota interés ayuda mucho. Si va a consulta hace la tarea con uno porque en clase explica a medias'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2026-01-11T00:00:00+00:00'::TIMESTAMPTZ, '7059ee0b4b52169bdd458b91d6c5709e5defe52bde2c82ad348630829597c42a'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Es muy buena persona, hace las clases y exámenes bastante claros. No califica duro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2025-12-22T00:00:00+00:00'::TIMESTAMPTZ, '0732cb10119e96d528bacccf2ff2bdcef762d03bf2250b0a4fd0b5b25e9f0b20'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Cancela las clases cuando se le antoja y las pocas que da son de 1 hora y media y para colmo solo habla de otras cosas en lugar de la materia. Para pasar es fácil, pero no se aprende nada, no lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-18T00:00:00+00:00'::TIMESTAMPTZ, '6105777b47210c59aabd396b987e0fd2151050165c9b8f595b87fdd170ff6e4d'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Pésimo profesor, habla de su vida personal y hace comentarios irreverentes en clase. Quiere hacerse amigo de los alumnos, no nos enseña nada. No lo matriculen'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-07-27T00:00:00+00:00'::TIMESTAMPTZ, '37958f11f49ae54d1231cf7fb072144c3c30d829209e1a4a863915c0e2c42d96'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Uno de los peores profes que he tenido en el TEC.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'd5363f2d35cb0a18ef454418a8d8f02fb0526927e12b4e8b2b7bc9498d2a0b9b'::TEXT, ARRAY[972]::BIGINT[]),
    (258::BIGINT, 'Lo peor del TEC, no enseña nada, a veces ponía vídeos de youtube que ni al caso con la clase, hace comentarios súper machistas cada que puede, y deja 3 exámenes cortos que uno dura 4 horas haciendo, y creo que el último ni lo revisa. Saquen a esta sanguijuela del TEC'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-07-14T00:00:00+00:00'::TIMESTAMPTZ, '6b699960023ad085cae8051193a86d2fbe7bb412e9775a1fd7343e7742825254'::TEXT, ARRAY[956]::BIGINT[]),
    (258::BIGINT, 'Excelente profesor, 100% humanitario, comprende y brinda ayuda a sus estudiantes, se toma el tiempo para explicar con detenimiento cada aspecto de cualquier tema. Uno de los mejores profesores con los que he podido matricular.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-12T00:00:00+00:00'::TIMESTAMPTZ, '3e2e43b2359e17e9417029f21357eccb840d758e1adb52f22f2f6e7976d00a73'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Un autentico idiota sin personalidad definida, homosexual reprimido y se le nota a kilometros su necesidad de verga. pesimo profesor y discrimina a las mujeres y le encanta citar a los maes a su oficina a solas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-15T00:00:00+00:00'::TIMESTAMPTZ, '66cdc6c77b7b8c9ec634ad2d9af815fa42cfef535b60042521554d2e3912858b'::TEXT, ARRAY[3088, 1733]::BIGINT[]),
    (258::BIGINT, 'El profesor tiene una personalidad extraña y tiene comentarios machistas. El curso en sí es fácil y los exámenes de hacen en grupo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'f21c1c28e99ddc53bdc4fa5b71e2b265f7c87fbc2b172a555763a93dba220a78'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Es demasiado vago, no revisa nada hasta semana 18. Deja hacer los exámenes en grupos.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'db6a9275b9321175ba810e06f90d50c4c205415b98accf413b980c9a6cc5785b'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, '0e26dad0fe91f053442a48c0d597e00624a639e7612cc4e3e1eb119d0f5a12b5'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Pésimo profesor, no entiendo cómo tienen a este vago de mierda en el tec robándose el salario. Es gay de closet y no tengo problema con eso, pero tener la poca vergüenza de tener preferencias con los maes guapos me parece una falta de respeto para los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-11T00:00:00+00:00'::TIMESTAMPTZ, 'ca41558d629c97f31c3013f80ce8adc8f9847f99d9ab22417336f47dd2395f53'::TEXT, ARRAY[956, 972]::BIGINT[]),
    (258::BIGINT, 'Es muy malo y vago, no se aprende casi nada en el curso, es como no llevarlo, si quiere pasar sin aprender llévelo con él, deja labs y tareas, pero no se realizan experimentos, son solo copiar cosas de otros y ya queda el reporte, a fin de semestre deja todo y no revisa nada, pone 100. Muy malo.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '61622fae4c12b6872780ef181deeb3c5b968b0862b110c4059ce8c47d40edd2a'::TEXT, ARRAY[972]::BIGINT[]),
    (258::BIGINT, 'Una falta de respeto a la población estudiantil tener a alguien así de incompetente dando cursos avanzados. Si quiere pasar el curso sin la mas minima preocupación, adelante, este profe es para usted.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, '54f95843af6c7fd817fc54b2c2b2c9026ddfbc7f01b54e3d68ba2dde7c158300'::TEXT, ARRAY[972]::BIGINT[]),
    (258::BIGINT, 'No me gusto para nada el curso, el profe es super desordenado y todas las semana sube como mil pdf en los cuales importa como una pagina. Las instrucciones del proyecto fueron cero claras y no revisó nada hasta el final . No lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'c4e4a99c5d860ff213cddf26c3f8f09a7b4b16647ddde5087985345c33fb5445'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'No esperaba mucho y aún así logró sorprenderme con el nivel de mediocridad que posee. Realmente no enseña nada, los temas los conversa literalmente, dibuja y escribe en las presentaciones cosas que ni el puede entender. Para mí, el peor profesor del TEC. Eso sí, tienes el curso aprobado si matrícula'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'be0e81a2b3a2b481eb677af938feec156535dd13b801a7e869a238f7f505c5b3'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Es un mamapichas, no sabe distinguir un tubo de pvc de uno de hierro negro asi se lo digo'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'f4912cc2c75940f151cacce57ae5a865647e821690e4d9e18d7e0a7ca9e02c94'::TEXT, ARRAY[956]::BIGINT[]),
    (258::BIGINT, 'Este profe no sabe ni donde está parado, dá el curso demasiado por encima, la verdad es un desperdicio de curso llevarlo con él'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '73aa8c57a9cbcaf84ad41c6e4e1aa26b317764a3edf399a8b80fb8141bb0bc13'::TEXT, ARRAY[972]::BIGINT[]),
    (258::BIGINT, 'Cursos para pasar con 100 y aprender 0. Acumula todas las evaluaciones y las asigna en semana 19. Finalmente no revisa nada y le pone 100 a todos.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'd3b84f030751f3b5f772cd2f723d3491c550d9f6f29c656ede4441f3d2d534d3'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '8ae92ff70f87e099f98ad8dc18ff751009e7dad585c19d5b4b3a004a9a73441a'::TEXT, ARRAY[972]::BIGINT[]),
    (258::BIGINT, 'Una verdadera Vergüenza, un profesor mediocre, no tiene el nivel de los profes del tec. No se aprende nada, todo lo regala, todo mundo pasa con 100 pero es porque no deja trabajos, super desordenado, no revisa los exámenes solo pone la nota. No lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'f3f2c8434b6b9f7c49c7ccac64a7cb5c551553ef6d845ef20b5376ae3062d6da'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Es el peor profesor que he tenido en mi vida, lo puedo jurar. Es de las personas más mediocres que conozco. Casi no deja evaluaciones (y a todo le pone 100), es un desorganizado dando la materia (y comete muchos errores en sus explicaciones), falta a clases varias veces. Asigna trabajos en semana 19'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '6c800efc78dddff9ef8b48112f77defbe5c874fa51f6b1bc2976ffbe5ffb44d1'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'En Máquinas virtual fue un desorden. La materia la daba demasiado confusa y los apuntes que hacía ni se entendían. Además solo habíamos tenido exámenes y quices y en semana 15 se acordó de las 3 tareas y el proyecto y lo puso todo de un solo. Aún asi es buena gente.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-12-07T00:00:00+00:00'::TIMESTAMPTZ, '50c785d3e673f60a932848dfe24bbdab8d9796836da42de3723e07b5975e4810'::TEXT, ARRAY[1733, 3088]::BIGINT[]),
    (258::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '70d4e0b87de7597bfac08f3259d8f30e64fc4e91d82b84a369365d6a5c25c8ed'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'En virtual fue bastante flexible, sí se tenían que hacer todas las tareas de cátedra pero daba más tiempo. Siempre llega a acuerdos con los estudiantes y graba todas las clases. Es fácil'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'd6f0c30b205e9f428ffe8ba18b0ddd5c63a87b0a034d10930446a1b52368eab8'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Es un profe excelente, ayuda bastante, es bastante flexible con la entrega de trabajos, además no hace la clase (que es de cuatro horas) tan pesada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-27T00:00:00+00:00'::TIMESTAMPTZ, 'b7944ca52a4df986bb8b17128872ac7a5e30bcf0bd57f358029de0f4ba7eec3b'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Es un buen profe y si le pone esfuerzo e interés él lo va a notar. Siempre está del lado del estudiante y de lo que mejor les convenga, siendo super flexibe con fechas de entrega y esas cosas. A veces le dan mates raros de actitud que nisiquiera siendo alumno de él se entienden.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'd57e47edcc140630b2f409c853c671e8a8f997666fcc3913f9ed69dffb223ab8'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Es un profesor jóven. Es un poco desordenado, pero comprende y entiende perfectamente a los estudiantes. Trabajos largos al inicio por la parte de dibujar, pero luego es muy fácil en computadora. Llega a acuerdos con los estudiantes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2019-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'bcd540306997084d2b5cd17201b9e200f69d8f97c6b6afbcf9808aea83daf0ae'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'El profesor es regular-bueno, su actitud es bipolar, sin embargo da el curso de manera decente para que todos puedan pasar. En muchas ocasiones genera confusiones, pero califica como debe ser. Se lo puedo recomendar para carreras que no necesiten mayor conocimiento de diseño.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-23T00:00:00+00:00'::TIMESTAMPTZ, '00a76a8c03ecf950aaa40f22b4dc855f86642fdc4f5e1f297e52cd32f809f7da'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Mal profe, no lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-10-30T00:00:00+00:00'::TIMESTAMPTZ, '2e30dd29d364e79e6f0e258c080fec15a4be6a3921a7f20094a49d9cb4180158'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Muy buen profesor, explicaba muy bien y preparaba apenas para sacar muy buena nota en los colegiados. Hay que hacer todas las tareas y practicas para que le vaya bien, exime si usted saca notas normales y entrega todas las tareas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '7949adaa08918ff179703534696af03eeee108a181c5a9422bb5effcc9799542'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Es bueno pero los ejemplos que se ven en clases son demasiado fáciles. Lo dificil del curso son los examenes colegiados.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-07T00:00:00+00:00'::TIMESTAMPTZ, '3a15c2aa99aa907c9c564a7a7275cd5ac7352abf2846893763367f17007a685d'::TEXT, ARRAY[1726]::BIGINT[]),
    (258::BIGINT, 'Se interesó más en sus clases de maestría que en el curso, explicaciones a medias, no deja tareas todas las semanas pero junta todas para entregar el día del examen. Ni se le ocurra matricular con él si tiene que llevar industrial. Además uno se da cuenta de su nota hasta en la entrega de actas.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '00fff0a99f2d13575b0af480b2a7c10f496ef0afce5fda24ee073a402eb188fa'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Si le caes bien, es muy buena gente pero si no, es muy sarcástico y grosero. Brinda el mucha ayuda cuando le place. Tendencias bipolares.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, '55f74758a1b1d30ab2cc2fd8da6f0043120adab14ce1d00a28afd60fc811b6d6'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'El mejor profe para dibujo técnico, siempre y cuando no tenga que llevar dibujo industrial. Ni lo dude, va a pasar y si le pone mínimo 90.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-09T00:00:00+00:00'::TIMESTAMPTZ, '4273b81be3909f0333a1ecc430d7abb627540fa773e00a2f54c24711c9bd96e1'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'El Profe es muy buena nota y en los exámenes lo ayuda a uno bastante, explica bien pero prácticamente que no devuelve las tareas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '79e97b8a6e99bc0694be9ca54426ff3c41871e890b00ae430e81f3e709fe4595'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Muy buen profesor, brinda mucha ayuda a los que se atrasan un poco.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '8d03b76570342d61b7b484839cced02e56531e690d421d373528a8dc65d3ffa1'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f51ca9fd135d71b3cf04c5e18f7d9f2652fa691dceeeee51e8096b80f6cd2dc3'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Es buen profe pero a veces piensa que ya toda la clase sabe todo y avanza muy rápido. Si saca el tiempo para ayudar. Hay que hacer bastante práctica y preguntarle por todo para poder entender las cosas del curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'b08d7624bdc13b2b426a2a6961efe1849e7792939c15bbdc85f9a3fa3530755c'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '7abaabb4883d2e7f105468b147fdeadda8d6eb25ca5c7a1849635951accaf740'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Trata de ser cómico, pero no lo es, aunque se esfuerza por serlo. Es muy agradable y ayuda demasiado. Si no entiendes saca el rato para que logres entender. Ayuda con sus tareas y trata de que todo quede claro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-05-10T00:00:00+00:00'::TIMESTAMPTZ, '97186e71ca6f73070900b28296b3a22045cdfdf094d63859fe83d4fd07349893'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'es muy facil, ayuda mucho pero si pierde mucho tiempo ayudando a otros y atrasa un poco. De fijo aprende y sale bien. Ayuda bastante'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, '7daa9ca57dcc422e478afec1fb8c5cc7673f1e5387ef6ccdbd9f3e80088501cc'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'es un excelente profesor la calidad humana 10 se entiende hace la materia agradable se aprende vale la pena con el en mis muchos años en el Tec nunca vi profesor mejor. y como dijo un compañero " nunca vi profe tan bueno"'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'a89b0e008cd774fc758d55806a983ae72519725ea86dbd60fe141f2d51cd98fc'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Ayuda mucho si no entiendes puede abarcar casi toda la clase explicándote, las tareas son fáciles, pero por ayudar tanto aveces no se abarca todo lo que se tenia que abarcar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-23T00:00:00+00:00'::TIMESTAMPTZ, '1174ca3239e607f32d9e3841eadabe6e4201f2c70fd21484d8e6ea3854e25310'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'No explica muy bien, pero el mae si es guapo ( ͡° ͜ʖ ͡°) #no_homo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'e3bf7f26bf662dfce635e65cf804c4049161bf58ad8786342aa7a851416cef2c'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'explica muy bien y por cierto es guapo el profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, '060f415c1776c993aa09f56811e1411b39a909b046a0270f225e56b54b9c2865'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2419899307ef7358314bcf20b84bd19b37304fbcf430df2bfdc4d55990609359'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Muy buen profe, dispuesto a ayudar y entiende razones. Es flexible y explica detenidamente siempre con gran disposición a ayudar. Muy recomendado, se aprende mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'cfa7ec5a9ff6e24799b7fd2414c3aac91011e358892106473ecd60a9a43c0b45'::TEXT, ARRAY[610]::BIGINT[]),
    (258::BIGINT, 'Aprenden a dibujar bien, este profe es para aquellos que nunca en su vida han llevado dibujo. Es flexible, enseña de verdad. Si lleban D. industrial, super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'fb08a7b78a43e3933b6b83d276a376620d5725be7fb039a5072155e3fd084d1d'::TEXT, ARRAY[610]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
